import csv
import io
import json


def export_json(items):
    return json.dumps(items)


def export_csv(items):
    output=io.StringIO()
    writer=csv.DictWriter(output,fieldnames=["name","quantity"])
    writer.writeheader()
    writer.writerows(items)
    return output.getvalue()


def export_items(items,format="csv"):
    return export_csv(items) if format=="csv" else export_json(items)

